func DetectPYC(b Buffer) *Metadata {
	if b.Len() < 4 {
		return nil
	}

	if b[2] != 0x0d || b[3] != 0x0a {
		return nil
	}

	magic, ok := b.U16LE(0)
	if !ok {
		return nil
	}

	if _, found := pycMagic[magic]; !found {
		return nil
	}

	return &Metadata{
		Kind: KindPythonBytecode,
	}
}

const qnx4SuperOffset = 512

func DetectQNX4(b Buffer) *Metadata {
	if !b.Has(qnx4SuperOffset, []byte{'/', 0}) {
		return nil
	}

	rootBlock, ok := b.U32LE(qnx4SuperOffset + 20)
	if !ok || rootBlock == 0 {
		return nil
	}

	rootBlocks, ok := b.U32LE(qnx4SuperOffset + 24)
	if !ok || rootBlocks == 0 {
		return nil
	}

	rootOffset := uint64(rootBlock-1) * 512
	rootSize := min(uint64(rootBlocks)*512, uint64(maxScanSize))

	if rootOffset > uint64(b.Len()) || rootSize > uint64(b.Len())-rootOffset {
		return nil
	}

	for offset := int(rootOffset); offset+64 <= int(rootOffset+rootSize); offset += 64 {
		if b.Has(offset, []byte(".bitmap\x00")) {
			return &Metadata{Kind: KindQNX4Filesystem}
		}
	}

	return nil
}

func DetectSkippableFrames(b Buffer) *Metadata {
	var skipped bool

	for b.Len() >= 8 && b[0]&0xf0 == 0x50 && b.Has(1, []byte{0x2a, 0x4d, 0x18}) {
		skipped = true

		length, _ := b.U32LE(4)
		if uint64(length) > uint64(b.Len()-8) {
			return &Metadata{Kind: KindZstandardLZ4Stream, Type: TypeSkinnableFrame, Confidence: ConfidenceMedium}
		}

		b = b[8+int(length):]
	}

	if !skipped {
		return nil
	}

	if b.Has(0, []byte{0x28, 0xb5, 0x2f, 0xfd}) {
		return &Metadata{Kind: KindZstandardArchive}
	}

	if b.Has(0, []byte{4, 0x22, 0x4d, 0x18}) {
		return &Metadata{Kind: KindLZ4Frame}
	}

	return &Metadata{Kind: KindZstandardLZ4Stream, Type: TypeSkinnableFrame}
}

func DetectSQLiteSHM(b Buffer) *Metadata {
	if b.Len() < 96 {
		return nil
	}

	if !bytes.Equal(b[:48], b[48:96]) {
		return nil
	}

	var typ TypeID

	if b[0] == 0x18 {
		typ = TypeLittleEndian
	} else if b[3] == 0x18 {
		typ = TypeBigEndian
	} else {
		return nil
	}

	return &Metadata{
		Kind: KindSQLite3SharedMemory,
		Type: typ,
	}
}

func DetectTar(b Buffer) *Metadata {
	var (
		isTar        bool
		hasOCILayout bool
		hasOCIIndex  bool
		hasOCIBlobs  bool
	)

	limit := min(b.Len(), maxScanSize)

	for offset := 0; offset+512 <= limit; {
		header := b[offset : offset+512]
		if header[0] == 0 || !validTarChecksum(header) {
			break
		}

		isTar = true

		nameEnd := bytes.IndexByte(header[:100], 0)
		if nameEnd == -1 {
			nameEnd = 100
		}

		prefixEnd := 0

		if string(header[257:262]) == "ustar" {
			prefixEnd = bytes.IndexByte(header[345:500], 0)
		}

		if prefixEnd == -1 {
			prefixEnd = 155
		}

		if nameEnd > 0 {
			name := header[:nameEnd]
			prefix := header[345 : 345+prefixEnd]

			switch {
			case tarPathEqual(prefix, name, "package/package.json"), tarPathEqual(prefix, name, "package.json"):
				return &Metadata{Kind: KindTARArchive, Type: TypeNpmPackage}
			case tarPathEqual(prefix, name, "oci-layout"):
				hasOCILayout = true
			case tarPathEqual(prefix, name, "index.json"):
				hasOCIIndex = true
			case bytes.HasPrefix(name, []byte("blobs/sha256/")) || bytes.HasPrefix(prefix, []byte("blobs/sha256")):
				hasOCIBlobs = true
			case tarPathEqual(prefix, name, "PKG-INFO"), tarPathEqual(prefix, name, "setup.py"), tarPathEqual(prefix, name, "pyproject.toml"):
				return &Metadata{Kind: KindTARArchive, Type: TypePythonSourceDistribution}
			case tarPathEqual(prefix, name, "info/index.json"):
				return &Metadata{Kind: KindTARArchive, Type: TypeCondaPackage}
			case tarPathEqual(prefix, name, ".PKGINFO"):
				return &Metadata{Kind: KindTARArchive, Type: TypeArchLinuxPackage}
			case tarPathEqual(prefix, name, "Vagrantfile"):
				return &Metadata{Kind: KindTARArchive, Type: TypeVagrantBox}
			case tarPathEqual(prefix, name, "install/doinst.sh"):
				return &Metadata{Kind: KindTARArchive, Type: TypeSlackwarePackage}
			case tarPathEqual(prefix, name, "ComicInfo.xml"), tarPathEqual(prefix, name, "comicinfo.xml"):
				return &Metadata{Kind: KindTARArchive, Type: TypeComicBook}
			case tarPathEqual(prefix, name, "metadata"), tarPathEqual(prefix, name, "deploy"):
				return &Metadata{Kind: KindTARArchive, Type: TypeFlatpak}
			}
		}

		size, ok := parseTarOctal(header[124:136])
		if !ok {
			break
		}

		remaining := uint64(limit - offset - 512)
		if size > remaining {
			break
		}

		padded := (size + 511) / 512 * 512
		if padded > remaining {
			break
		}

		next := offset + 512 + int(padded)
		if next <= offset {
			break
		}

		offset = next
	}

	if isTar {
		if hasOCILayout && hasOCIIndex && hasOCIBlobs {
			return &Metadata{Kind: KindTARArchive, Type: TypeOCIImageLayout}
		}

		return &Metadata{Kind: KindTARArchive}
	}

	return nil
}

func validTarChecksum(header []byte) bool {
	stored, ok := parseTarOctal(header[148:156])
	if !ok {
		return false
	}

	var (
		unsignedSum uint64
		signedSum   int64
	)

	for i, value := range header {
		if i >= 148 && i < 156 {
			value = ' '
		}

		unsignedSum += uint64(value)
		signedSum += int64(int8(value))
	}

	return unsignedSum == stored || signedSum >= 0 && uint64(signedSum) == stored
}

func parseTarOctal(field []byte) (uint64, bool) {
	if len(field) > 0 && field[0]&0x80 != 0 {
		if field[0]&0x40 != 0 {
			return 0, false
		}

		value := uint64(field[0] & 0x3f)

		for _, part := range field[1:] {
			if value > (^uint64(0)-uint64(part))/256 {
				return 0, false
			}

			value = value*256 + uint64(part)
		}

		return value, true
	}

	field = bytes.Trim(field, " \x00")
	if len(field) == 0 {
		return 0, false
	}

	var value uint64

	for _, digit := range field {
		if digit < '0' || digit > '7' {
			return 0, false
		}

		value = value*8 + uint64(digit-'0')
	}

	return value, true
}

func tarPathEqual(prefix []byte, name []byte, target string) bool {
	if len(prefix) == 0 {
		return string(name) == target
	}

	return len(prefix)+1+len(name) == len(target) && string(prefix) == target[:len(prefix)] && target[len(prefix)] == '/' && string(name) == target[len(prefix)+1:]
}

func DetectText(b Buffer) *Metadata {
	if b.Len() == 0 {
		return nil
	}

	if !passesTextLengthGate(b) {
		return nil
	}

	var (
		content  []byte
		encoding TypeID
		isASCII  bool
		isUTF8   bool
		isLatin1 bool
	)

	detectedEncoding, hasEncoding := DetectTextEncoding(b)
	if hasEncoding {
		switch detectedEncoding {
		case TypeUTF16LE, TypeUTF16BE:
			decoded, _, ok := TryDecodeUTF16(b)
			if ok && len(decoded) > 0 {
				content = decoded
				encoding = detectedEncoding
			} else {
				content = b
			}
		case TypeUTF32LE, TypeUTF32BE:
			content = b
			encoding = detectedEncoding
		case TypeUTF8:
			if b.Len() > 3 {
				content = b[3:]
			} else {
				content = b
			}

			encoding = detectedEncoding
		default:
			content = b
		}
	} else {
		content = b

		isASCII = isLikelyASCIIText(content)
		if !isASCII {
			isUTF8 = isLikelyTextUTF8(content)
		}

		if !isASCII && !isUTF8 && isLikelyLatin1(b) {
			isLatin1 = true
		}
	}

	if encoding == TypeNone {
		if isASCII {
			encoding = TypeASCII
		} else if isUTF8 {
			encoding = TypeUTF8
		} else if isLatin1 {
			encoding = TypeLatin1
		} else {
			return nil
		}
	}

	limit := min(len(content), 4096)
	subtype := detectTextSubtype(content[:limit])

	if subtype != TypeNone {
		return &Metadata{
			Kind:       KindText,
			Type:       subtype,
			Confidence: ConfidenceMedium,
		}
	}

	return &Metadata{
		Kind:       KindText,
		Type:       encoding,
		Confidence: ConfidenceLow,
	}
}

func detectTextSubtype(data []byte) TypeID {
	trimmed := bytes.TrimSpace(data)
	if len(trimmed) == 0 {
		return TypeNone
	}

	if bytes.HasPrefix(data, []byte("#!")) {
		lineEnd := bytes.IndexByte(data, '\n')
		if lineEnd == -1 {
			lineEnd = len(data)
		}

		shebang := data[:lineEnd]

		if bytes.Contains(shebang, []byte("bash")) || bytes.Contains(shebang, []byte("/sh")) {
			return TypeBashScript
		}

		if bytes.Contains(shebang, []byte("python")) {
			return TypePythonScript
		}

		if bytes.Contains(shebang, []byte("node")) {
			return TypeJavaScriptSource
		}

		if bytes.Contains(shebang, []byte("perl")) {
			return TypePerlScript
		}

		if bytes.Contains(shebang, []byte("ruby")) {
			return TypeRubyScript
		}

		if bytes.Contains(shebang, []byte("php")) {
			return TypePHPScript
		}

		if bytes.Contains(shebang, []byte("lua")) {
			return TypeLuaScript
		}

		if bytes.Contains(shebang, []byte("Rscript")) || bytes.Contains(shebang, []byte("R ")) {
			return TypeRScript
		}

		if bytes.Contains(shebang, []byte("fish")) {
			return TypeFishScript
		}

		if bytes.Contains(shebang, []byte("zsh")) {
			return TypeZshScript
		}

		if bytes.Contains(shebang, []byte("guile")) || bytes.Contains(shebang, []byte("scheme")) {
			return TypeGuileScript
		}

		if bytes.Contains(shebang, []byte("emacs")) || bytes.Contains(shebang, []byte("elisp")) {
			return TypeEmacsLispScript
		}

		if bytes.Contains(shebang, []byte("clojure")) || bytes.Contains(shebang, []byte("clj")) {
			return TypeClojureScript
		}

		if bytes.Contains(shebang, []byte("elixir")) {
			return TypeElixirScript
		}

		if bytes.Contains(shebang, []byte("haskell")) || bytes.Contains(shebang, []byte("runhaskell")) {
			return TypeHaskellSource
		}

		if bytes.Contains(shebang, []byte("nix")) {
			return TypeNixExpression
		}

		if bytes.Contains(shebang, []byte("fsharpi")) || bytes.Contains(shebang, []byte("fsharp")) {
			return TypeFSharpSource
		}
	}

	if bytes.HasPrefix(trimmed, []byte("<?php")) {
		return TypePHPScript
	}

	if bytes.HasPrefix(trimmed, []byte("FROM ")) || bytes.HasPrefix(trimmed, []byte("# syntax=")) {
		return TypeDockerfile
	}

	if bytes.Contains(trimmed, []byte("version:")) && bytes.Contains(trimmed, []byte("services:")) {
		return TypeDockerComposeConfiguration
	}

	if bytes.HasPrefix(trimmed, []byte("# ")) || bytes.HasPrefix(trimmed, []byte("## ")) {

		if bytes.Contains(trimmed, []byte("- [ ]")) || bytes.Contains(trimmed, []byte("- [x]")) {
			return TypeMarkdownDocument
		}

		if bytes.Contains(trimmed, []byte("```")) {
			return TypeMarkdownDocument
		}

		if bytes.Contains(trimmed, []byte("| ")) && bytes.Contains(trimmed, []byte("|---")) {
			return TypeMarkdownDocument
		}

		return TypeMarkdownDocument
	}

	if bytes.HasPrefix(trimmed, []byte("---\n")) || bytes.HasPrefix(trimmed, []byte("---\r\n")) {
		if bytes.Contains(trimmed, []byte("title:")) || bytes.Contains(trimmed, []byte("layout:")) {
			return TypeMarkdownDocument
		}

		if bytes.Contains(trimmed, []byte("apiVersion:")) || bytes.Contains(trimmed, []byte("kind:")) {
			return TypeYAMLConfiguration
		}

		if bytes.Contains(trimmed, []byte("services:")) || bytes.Contains(trimmed, []byte("version:")) {
			return TypeDockerComposeConfiguration
		}

		return TypeYAMLConfiguration
	}

	if bytes.HasPrefix(trimmed, []byte("CREATE TABLE")) || bytes.HasPrefix(trimmed, []byte("SELECT ")) || bytes.HasPrefix(trimmed, []byte("INSERT INTO")) || bytes.HasPrefix(trimmed, []byte("-- SQL")) || bytes.HasPrefix(trimmed, []byte("ALTER TABLE")) || bytes.HasPrefix(trimmed, []byte("DROP TABLE")) {
		return TypeSQLScript
	}

	if bytes.HasPrefix(trimmed, []byte("@echo off")) || bytes.HasPrefix(trimmed, []byte("@ECHO OFF")) || bytes.HasPrefix(trimmed, []byte("REM ")) || bytes.HasPrefix(trimmed, []byte("rem ")) {
		return TypeBatchScript
	}

	if bytes.HasPrefix(trimmed, []byte("cmake_minimum_required")) || bytes.HasPrefix(trimmed, []byte("project(")) {
		return TypeCMakeScript
	}

	if bytes.HasPrefix(trimmed, []byte("body {")) || bytes.HasPrefix(trimmed, []byte("@import url(")) || bytes.HasPrefix(trimmed, []byte("@media ")) || bytes.HasPrefix(trimmed, []byte(":root {")) || bytes.HasPrefix(trimmed, []byte("@keyframes")) {
		return TypeCSS
	}

	if bytes.HasPrefix(trimmed, []byte("resource \"")) || bytes.HasPrefix(trimmed, []byte("variable \"")) || bytes.HasPrefix(trimmed, []byte("provider \"")) || bytes.HasPrefix(trimmed, []byte("terraform {")) || bytes.HasPrefix(trimmed, []byte("module \"")) {
		if bytes.Contains(trimmed, []byte("module \"")) {
			return TypeTerraformModule
		}

		return TypeTerraformConfiguration
	}

	if bytes.HasPrefix(trimmed, []byte("schema {")) || bytes.HasPrefix(trimmed, []byte("type ")) && bytes.Contains(trimmed, []byte("{")) && bytes.Contains(trimmed, []byte("}")) {
		return TypeGraphQLSchema
	}

	if bytes.HasPrefix(trimmed, []byte("query {")) || bytes.HasPrefix(trimmed, []byte("mutation {")) || bytes.HasPrefix(trimmed, []byte("fragment ")) {
		return TypeGraphQL
	}

	if bytes.HasPrefix(trimmed, []byte("syntax = \"proto")) || bytes.HasPrefix(trimmed, []byte("package ")) && bytes.Contains(trimmed, []byte("message ")) {
		return TypeProtocolBuffer
	}

	if bytes.HasPrefix(trimmed, []byte("namespace ")) && (bytes.Contains(trimmed, []byte("service ")) || bytes.Contains(trimmed, []byte("struct "))) {
		return TypeThriftInterface
	}

	if bytes.Contains(trimmed, []byte("openapi:")) || bytes.Contains(trimmed, []byte("\"openapi\"")) || bytes.Contains(trimmed, []byte("swagger:")) {
		return TypeOpenAPISpecification
	}

	if bytes.HasPrefix(trimmed, []byte("# shellcheck")) {
		return TypeShellcheckDirective
	}

	if bytes.HasPrefix(trimmed, []byte("set ")) || bytes.HasPrefix(trimmed, []byte("let ")) || bytes.HasPrefix(trimmed, []byte("function! ")) || bytes.HasPrefix(trimmed, []byte("call ")) {
		if bytes.Contains(trimmed, []byte("nmap ")) || bytes.Contains(trimmed, []byte("imap ")) || bytes.Contains(trimmed, []byte("vmap ")) || bytes.Contains(trimmed, []byte("syntax ")) {
			return TypeVimScript
		}
	}

	code := skipCStyleComments(trimmed)
	if len(code) == 0 {
		return TypeNone
	}

	if bytes.HasPrefix(code, []byte("package ")) {
		if bytes.Contains(code, []byte("import (")) || bytes.Contains(code, []byte("import \"")) || bytes.Contains(code, []byte("func ")) {
			return TypeGoSource
		}

		if bytes.Contains(code, []byte("import java")) || bytes.Contains(code, []byte("public class ")) {
			return TypeJavaSource
		}

		if bytes.Contains(code, []byte("import ")) || bytes.Contains(code, []byte("fun ")) || bytes.Contains(code, []byte("val ")) {
			return TypeKotlinSource
		}

		if bytes.Contains(code, []byte("import scala.")) || bytes.Contains(code, []byte("object ")) || bytes.Contains(code, []byte("trait ")) {
			return TypeScalaSource
		}
	}

	if bytes.HasPrefix(code, []byte("defmodule ")) {
		return TypeElixirScript
	}

	if bytes.HasPrefix(code, []byte("module ")) && (bytes.Contains(code, []byte("where ")) || bytes.Contains(code, []byte("import "))) {
		return TypeHaskellSource
	}

	if bytes.HasPrefix(code, []byte("(ns ")) {
		return TypeClojureScript
	}

	if bytes.HasPrefix(code, []byte("#include <")) || bytes.HasPrefix(code, []byte("#include \"")) {
		if bytes.Contains(code, []byte("std::")) || bytes.Contains(code, []byte("class ")) || bytes.Contains(code, []byte("template <")) {
			return TypeCPPSource
		}

		if bytes.Contains(code, []byte("module ")) && bytes.Contains(code, []byte("endmodule")) {
			if bytes.Contains(code, []byte("logic ")) || bytes.Contains(code, []byte("always_comb")) || bytes.Contains(code, []byte("always_ff")) {
				return TypeSystemVerilogSource
			}

			return TypeVerilogSource
		}

		if bytes.Contains(code, []byte("entity ")) && bytes.Contains(code, []byte("end ")) {
			return TypeVHDLSource
		}

		return TypeCSource
	}

	if bytes.HasPrefix(code, []byte("#import <")) || bytes.HasPrefix(code, []byte("#import \"")) {
		return TypeObjectiveCSource
	}

	if bytes.HasPrefix(code, []byte("using System;")) || bytes.HasPrefix(code, []byte("namespace ")) {
		if bytes.Contains(code, []byte("public class ")) || bytes.Contains(code, []byte("public interface ")) {
			return TypeCSharpSource
		}
	}

	if bytes.HasPrefix(code, []byte("import Foundation")) || bytes.HasPrefix(code, []byte("import UIKit")) || bytes.HasPrefix(code, []byte("import SwiftUI")) {
		return TypeSwiftSource
	}

	if bytes.HasPrefix(code, []byte("fn main()")) || bytes.HasPrefix(code, []byte("use std::")) || bytes.HasPrefix(code, []byte("pub fn ")) || bytes.HasPrefix(code, []byte("#![")) || bytes.HasPrefix(code, []byte("#[derive(")) || bytes.HasPrefix(code, []byte("#[allow(")) {
		return TypeRustSource
	}

	if bytes.HasPrefix(code, []byte("const std = @import(")) || bytes.Contains(code, []byte("pub fn ")) {
		return TypeZigSource
	}

	if bytes.Contains(code, []byte("proc ")) && bytes.Contains(code, []byte("=")) && bytes.Contains(code, []byte("import ")) {
		return TypeNimSource
	}

	if bytes.HasPrefix(code, []byte("pragma solidity")) {
		return TypeSoliditySource
	}

	if bytes.HasPrefix(code, []byte("open ")) || bytes.HasPrefix(code, []byte("let ")) {
		if bytes.Contains(code, []byte("type ")) && bytes.Contains(code, []byte("member ")) {
			return TypeFSharpSource
		}
	}

	if bytes.HasPrefix(code, []byte("{ config")) || bytes.HasPrefix(code, []byte("with import")) || bytes.HasPrefix(code, []byte("let ")) && bytes.Contains(code, []byte("in ")) {
		if bytes.Contains(code, []byte("pkgs.")) || bytes.Contains(code, []byte("stdenv")) || bytes.Contains(code, []byte("fetchurl")) {
			return TypeNixExpression
		}
	}

	if bytes.HasPrefix(code, []byte("Theorem ")) || bytes.HasPrefix(code, []byte("Lemma ")) || bytes.HasPrefix(code, []byte("Definition ")) {
		if bytes.Contains(code, []byte("Proof.")) {
			return TypeCoqSource
		}
	}

	if bytes.HasPrefix(code, []byte("theorem ")) || bytes.HasPrefix(code, []byte("lemma ")) || bytes.HasPrefix(code, []byte("def ")) {
		if bytes.Contains(code, []byte("by ")) {
			return TypeLeanSource
		}
	}

	if bytes.HasPrefix(code, []byte("module ")) && bytes.Contains(code, []byte("where ")) {
		if bytes.Contains(code, []byte("data ")) || bytes.Contains(code, []byte("total ")) {
			return TypeIdrisSource
		}
	}

	if bytes.HasPrefix(code, []byte("import ")) || bytes.HasPrefix(code, []byte("def ")) || bytes.HasPrefix(code, []byte("class ")) {
		if bytes.Contains(code, []byte("def ")) && bytes.Contains(code, []byte(":")) {
			return TypePythonScript
		}
	}

	if bytes.HasPrefix(code, []byte("require '")) || bytes.HasPrefix(code, []byte("require \"")) || bytes.HasPrefix(code, []byte("require_relative ")) {
		if bytes.Contains(code, []byte("def ")) || bytes.Contains(code, []byte("class ")) || bytes.Contains(code, []byte("module ")) {
			return TypeRubyScript
		}
	}

	if bytes.HasPrefix(code, []byte("local ")) || bytes.HasPrefix(code, []byte("function ")) || bytes.HasPrefix(code, []byte("require ")) || bytes.HasPrefix(code, []byte("require(\"")) {
		if bytes.Contains(code, []byte("end")) || bytes.Contains(code, []byte(" then")) || bytes.Contains(code, []byte(" do")) || bytes.Contains(code, []byte(".lua")) {
			return TypeLuaScript
		}
	}

	if bytes.HasPrefix(code, []byte("import 'package:")) || bytes.HasPrefix(code, []byte("import 'dart:")) {
		return TypeDartSource
	}

	if bytes.HasPrefix(code, []byte("library(")) || bytes.HasPrefix(code, []byte("require(")) {
		if bytes.Contains(code, []byte("<-")) || bytes.Contains(code, []byte("%>%")) {
			return TypeRScript
		}
	}

	if bytes.HasPrefix(code, []byte("import React")) || bytes.HasPrefix(code, []byte("from 'react")) || bytes.HasPrefix(code, []byte("from \"react")) {
		if bytes.Contains(code, []byte("export default function")) || bytes.Contains(code, []byte("const ")) && bytes.Contains(code, []byte("= ()")) {
			return TypeReactComponent
		}
	}

	if bytes.HasPrefix(code, []byte("<template>")) || (bytes.HasPrefix(code, []byte("<script")) && bytes.Contains(code, []byte("</template>"))) {
		if bytes.Contains(code, []byte("export default")) {
			return TypeVueComponent
		}
	}

	if bytes.HasPrefix(code, []byte("@Component(")) || bytes.HasPrefix(code, []byte("@NgModule(")) {
		return TypeAngularComponent
	}

	if bytes.HasPrefix(code, []byte("<script>")) || bytes.HasPrefix(code, []byte("<svelte:")) {
		return TypeSvelteComponent
	}

	if bytes.HasPrefix(code, []byte("{% extends")) || bytes.HasPrefix(code, []byte("{% block")) || bytes.HasPrefix(code, []byte("{% load")) {
		return TypeDjangoTemplate
	}

	if bytes.HasPrefix(code, []byte("{# ")) || bytes.HasPrefix(code, []byte("{% ")) || bytes.HasPrefix(code, []byte("{{ ")) {
		return TypeJinjaTemplate
	}

	if bytes.HasPrefix(code, []byte("{{define ")) || bytes.HasPrefix(code, []byte("{{if ")) || bytes.HasPrefix(code, []byte("{{range ")) || bytes.HasPrefix(code, []byte("{{template ")) {
		return TypeGoTemplate
	}

	if bytes.HasPrefix(code, []byte("{{#each ")) || bytes.HasPrefix(code, []byte("{{#if ")) || bytes.HasPrefix(code, []byte("{{#with ")) {
		return TypeHandlebarsTemplate
	}

	if bytes.HasPrefix(code, []byte("\\documentclass")) || bytes.HasPrefix(code, []byte("\\begin{document}")) {
		return TypeLaTeXDocument
	}

	if bytes.HasPrefix(code, []byte("\\input ")) || bytes.HasPrefix(code, []byte("\\include ")) {
		return TypeTeXDocument
	}

	if bytes.HasPrefix(code, []byte(".. ")) || bytes.HasPrefix(code, []byte("=======")) || bytes.HasPrefix(code, []byte("-------")) {
		return TypeReStructuredText
	}

	if bytes.HasPrefix(code, []byte("= ")) || bytes.HasPrefix(code, []byte("== ")) || bytes.HasPrefix(code, []byte(":")) && bytes.Contains(code, []byte(": ")) {
		return TypeAsciiDoc
	}

	if bytes.HasPrefix(code, []byte("#+TITLE:")) || bytes.HasPrefix(code, []byte("#+BEGIN_")) || bytes.HasPrefix(code, []byte("* ")) {
		return TypeOrgMode
	}

	if (trimmed[0] == '{' || trimmed[0] == '[') && (bytes.Contains(trimmed, []byte("//")) || bytes.Contains(trimmed, []byte("/*"))) {
		if bytes.Contains(trimmed, []byte(`":`)) || bytes.Contains(trimmed, []byte(`": `)) {
			return TypeJSONCSource
		}
	}

	if (trimmed[0] == '{' || trimmed[0] == '[') && bytes.Contains(trimmed, []byte("':")) {
		return TypeJSON5Source
	}

	if bytes.HasPrefix(code, []byte("const ")) || bytes.HasPrefix(code, []byte("let ")) || bytes.HasPrefix(code, []byte("var ")) || bytes.HasPrefix(code, []byte("import ")) {
		if bytes.Contains(code, []byte("interface ")) || bytes.Contains(code, []byte("type ")) || bytes.Contains(code, []byte(" as ")) || bytes.Contains(code, []byte(": string")) || bytes.Contains(code, []byte(": number")) || bytes.Contains(code, []byte(": boolean")) {
			if bytes.Contains(code, []byte("=>")) || bytes.Contains(code, []byte("console.log")) || bytes.Contains(code, []byte("from '")) || bytes.Contains(code, []byte("from \"")) {
				return TypeTypeScriptSource
			}
		}

		if bytes.Contains(code, []byte("=>")) || bytes.Contains(code, []byte("console.log")) || bytes.Contains(code, []byte("function(")) || bytes.Contains(code, []byte("function ")) {
			return TypeJavaScriptSource
		}
	}

	if bytes.HasPrefix(code, []byte("[")) {
		lineEnd := bytes.IndexByte(code, '\n')
		if lineEnd != -1 && bytes.Contains(code[:lineEnd], []byte("]")) {
			if bytes.Contains(code, []byte("=\"")) || bytes.Contains(code, []byte("= \"")) || bytes.Contains(code, []byte("['")) {
				return TypeTOMLConfiguration
			}

			if bytes.Contains(code, []byte("[remote")) || bytes.Contains(code, []byte("[branch")) || bytes.Contains(code, []byte("[core")) || bytes.Contains(code, []byte("[user")) {
				return TypeGitConfig
			}

			if bytes.Contains(code, []byte("Host ")) || bytes.Contains(code, []byte("[host")) {
				return TypeSSHConfig
			}

			return TypeINIConfiguration
		}
	}

	if bytes.HasPrefix(code, []byte("CFLAGS")) || bytes.HasPrefix(code, []byte("TARGET")) || bytes.HasPrefix(code, []byte("all:")) || bytes.HasPrefix(code, []byte(".PHONY:")) {
		return TypeMakefile
	}

	if bytes.Contains(code, []byte("Write-Host ")) || bytes.Contains(code, []byte("Get-")) || bytes.Contains(code, []byte("Set-")) || bytes.Contains(code, []byte("Out-Null")) {
		if bytes.Contains(code, []byte("$")) && (bytes.Contains(code, []byte("-eq")) || bytes.Contains(code, []byte("-ne")) || bytes.Contains(code, []byte("param("))) {
			return TypePowerShellScript
		}
	}

	if bytes.HasPrefix(code, []byte("#")) && bytes.Contains(trimmed, []byte("=")) && !bytes.Contains(trimmed, []byte("==")) {
		return TypePropertiesFile
	}

	if bytes.Count(trimmed, []byte(",")) > 3 && bytes.Count(trimmed, []byte("\n")) > 1 {
		lines := bytes.Split(trimmed, []byte("\n"))
		if len(lines) > 1 {
			firstLineCommas := bytes.Count(lines[0], []byte(","))
			secondLineCommas := bytes.Count(lines[1], []byte(","))

			if firstLineCommas > 0 && firstLineCommas == secondLineCommas {
				return TypeCSVData
			}
		}
	}

	if bytes.Count(trimmed, []byte("\t")) > 5 && bytes.Count(trimmed, []byte("\n")) > 2 {
		lines := bytes.Split(trimmed, []byte("\n"))
		if len(lines) > 2 {
			firstLineTabs := bytes.Count(lines[0], []byte("\t"))
			secondLineTabs := bytes.Count(lines[1], []byte("\t"))

			if firstLineTabs >= 2 && firstLineTabs == secondLineTabs {
				return TypeTSVData
			}
		}
	}

	if bytes.Contains(trimmed, []byte(" [INFO] ")) || bytes.Contains(trimmed, []byte(" [WARN] ")) || bytes.Contains(trimmed, []byte(" [ERROR] ")) || bytes.Contains(trimmed, []byte(" [DEBUG] ")) {
		return TypeLogData
	}

	if bytes.Contains(trimmed, []byte("\"GET ")) || bytes.Contains(trimmed, []byte("\"POST ")) || bytes.Contains(trimmed, []byte("\"PUT ")) {
		if bytes.Contains(trimmed, []byte("HTTP/")) {
			return TypeApacheLog
		}
	}

	if bytes.Contains(trimmed, []byte(" - - [")) && bytes.Contains(trimmed, []byte("] \"")) {
		return TypeNginxLog
	}

	if bytes.Contains(trimmed, []byte("HTTP/1.")) && bytes.Contains(trimmed, []byte(" 200 ")) || bytes.Contains(trimmed, []byte(" 301 ")) || bytes.Contains(trimmed, []byte(" 404 ")) {
		return TypeHTTPLog
	}

	if bytes.HasPrefix(trimmed, []byte("diff --git")) || bytes.HasPrefix(trimmed, []byte("index ")) || bytes.HasPrefix(trimmed, []byte("--- a/")) || bytes.HasPrefix(trimmed, []byte("+++ b/")) {
		return TypeGitDiff
	}

	if bytes.HasPrefix(trimmed, []byte("--- ")) || bytes.HasPrefix(trimmed, []byte("+++ ")) || bytes.HasPrefix(trimmed, []byte("@@ ")) {
		return TypeDiffPatch
	}

	if bytes.HasPrefix(trimmed, []byte("Merge ")) || (bytes.Contains(trimmed, []byte("\n\n")) && !bytes.Contains(trimmed, []byte("{")) && !bytes.Contains(trimmed, []byte("("))) {
		lines := bytes.Split(trimmed, []byte("\n"))
		if len(lines) > 0 && len(lines[0]) < 80 && !bytes.Contains(lines[0], []byte(":")) && !bytes.Contains(lines[0], []byte("=")) {
			return TypeCommitMessage
		}
	}

	return TypeNone
}

func skipCStyleComments(b []byte) []byte {
	for len(b) > 0 {
		b = bytes.TrimSpace(b)
		if bytes.HasPrefix(b, []byte("//")) {
			idx := bytes.IndexByte(b, '\n')
			if idx == -1 {
				return nil
			}

			b = b[idx:]
		} else if bytes.HasPrefix(b, []byte("/*")) {
			idx := bytes.Index(b, []byte("*/"))
			if idx == -1 {
				return nil
			}

			b = b[idx+2:]
		} else {
			break
		}
	}

	return b
}

func passesTextLengthGate(b Buffer) bool {
	if b.Len() >= 16 {
		return true
	}

	return bytes.ContainsAny(b, " \t\r\n")
}

func isLikelyASCIIText(b Buffer) bool {
	limit := min(b.Len(), 4096)
	if limit == 0 {
		return false
	}

	var printable int

	target := b[:limit]

	for _, c := range target {
		if c == 0 {
			return false
		}

		if c == '\n' || c == '\r' || c == '\t' || (c >= 32 && c <= 126) {
			printable++
		}
	}

	return printable*100/limit >= 95
}

func isLikelyTextUTF8(b Buffer) bool {
	limit := min(b.Len(), 4096)
	if limit == 0 {
		return false
	}

	target := b[:limit]
	if !utf8.Valid(target) {
		return false
	}

	var printable int

	for _, c := range target {
		if c == 0 {
			return false
		}

		if c == '\n' || c == '\r' || c == '\t' || c >= 32 {
			printable++
		}
	}

	return printable*100/limit >= 90
}

func Detect3DStudio(b Buffer) *Metadata {
	if !b.Has(0, []byte{0x4d, 0x4d}) {
		return nil
	}

	chunkSize, ok := b.U32LE(2)
	if !ok || chunkSize < 12 {
		return nil
	}

	child, ok := b.U16LE(6)
	if !ok || child != 0x0002 && child != 0x3d3d && child != 0xb000 {
		return nil
	}

	return &Metadata{Kind: Kind3DStudioMaxModel}
}

const (
	tiffLittleEndian tiffByteOrder = iota
	tiffBigEndian
)

type tiffByteOrder uint8

func DetectTIFFSubtypes(b Buffer) *Metadata {
	return DetectTIFFReaderAt(b, bytes.NewReader(b), int64(b.Len()))
}

func DetectTIFFReaderAt(b Buffer, reader io.ReaderAt, size int64) *Metadata {
	if b.Has(0, []byte{'I', 'I', 'U', 0x00, 0x18, 0x00, 0x00, 0x00}) {
		return &Metadata{Kind: KindTIFFImage, Type: TypePanasonicRAW}
	}

	if !isTIFFHeader(b) {
		if b.Has(0, []byte{'I', 'I', 'R', 'O', 0x08, 0x00}) || b.Has(0, []byte{'M', 'M', 'O', 'R', 0x00, 0x00}) {
			return &Metadata{Kind: KindTIFFImage, Type: TypeOlympusRAW}
		}

		return nil
	}

	if b.Has(0, []byte{'I', 'I', 0x2a, 0x00}) && b.Has(8, []byte{'C', 'R', 2, 0}) && b.Len() >= 16 {
		return &Metadata{Kind: KindCanonRAWImage, Type: TypeCanonRAW2}
	}

	order, ifd0, ok := tiffHeaderInfo(b)
	if !ok {
		if b.Has(0, []byte{'I', 'I'}) {
			return &Metadata{Kind: KindTIFFImage, Type: TypeLittleEndian}
		}

		return &Metadata{Kind: KindTIFFImage, Type: TypeBigEndian}
	}

	if tiffHasTag(b, order, ifd0, 0xc612) {
		return &Metadata{Kind: KindTIFFImage, Type: TypeAdobeDNG}
	}

	makeValue, ok := tiffASCIIValueForTag(b, order, ifd0, 0x010f)
	budget := 32

	if ok && tiffHasRawImage(reader, size, order, ifd0, 0, &budget) {
		if bytes.HasPrefix(makeValue, []byte("NIKON")) || bytes.HasPrefix(makeValue, []byte("Nikon")) {
			return &Metadata{Kind: KindTIFFImage, Type: TypeNikonRAW}
		}

		if bytes.HasPrefix(makeValue, []byte("OLYMPUS")) || bytes.HasPrefix(makeValue, []byte("Olympus")) {
			return &Metadata{Kind: KindTIFFImage, Type: TypeOlympusRAW}
		}

		if bytes.HasPrefix(makeValue, []byte("PENTAX")) {
			return &Metadata{Kind: KindTIFFImage, Type: TypePentaxRAW}
		}

		if bytes.HasPrefix(makeValue, []byte("SONY")) {
			return &Metadata{Kind: KindTIFFImage, Type: TypeSonyRAW}
		}
	}

	if b.Has(0, []byte{'I', 'I'}) {
		return &Metadata{Kind: KindTIFFImage, Type: TypeLittleEndian}
	}

	return &Metadata{Kind: KindTIFFImage, Type: TypeBigEndian}
}

func tiffHasRawImage(reader io.ReaderAt, size int64, order tiffByteOrder, ifdOffset uint32, depth int, budget *int) bool {
	if depth > 4 || *budget == 0 || int64(ifdOffset)+2 > size {
		return false
	}

	*budget--

	var header [2]byte

	if !readAtExactly(reader, header[:], int64(ifdOffset)) {
		return false
	}

	count, _ := tiffU16(header[:], order, 0)

	length := int(count) * 12
	if length > 4096 || int64(length) > size-int64(ifdOffset)-2 {
		return false
	}

	b := make(Buffer, length)
	if !readAtExactly(reader, b, int64(ifdOffset)+2) {
		return false
	}

	for index := range int(count) {
		entry := index * 12

		tag, _ := tiffU16(b, order, entry)
		fieldType, _ := tiffU16(b, order, entry+2)
		items, _ := tiffU32(b, order, entry+4)

		if tag == 0x0106 && fieldType == 3 && items == 1 {
			value, _ := tiffU16(b, order, entry+8)
			if value == 32803 || value == 34892 {
				return true
			}
		}

		if tag == 0x014a && fieldType == 4 && items > 0 && items <= 16 {
			var offsets [64]byte

			values := b[entry+8 : entry+12]

			if items > 1 {
				position, _ := tiffU32(b, order, entry+8)
				values = offsets[:int(items)*4]

				if int64(position)+int64(len(values)) > size || !readAtExactly(reader, values, int64(position)) {
					continue
				}
			}

			for child := range int(items) {
				childIFD, _ := tiffU32(values, order, child*4)
				if childIFD > ifdOffset && tiffHasRawImage(reader, size, order, childIFD, depth+1, budget) {
					return true
				}
			}
		}
	}

	return false
}

func tiffHeaderInfo(b Buffer) (tiffByteOrder, uint32, bool) {
	if b.Has(0, []byte{'I', 'I', 42, 0}) {
		ifd0, ok := b.U32LE(4)
		if !ok || ifd0 >= uint32(b.Len()) {
			return 0, 0, false
		}

		return tiffLittleEndian, ifd0, true
	}

	if b.Has(0, []byte{'M', 'M', 0, 42}) {
		ifd0, ok := b.U32BE(4)
		if !ok || ifd0 >= uint32(b.Len()) {
			return 0, 0, false
		}

		return tiffBigEndian, ifd0, true
	}

	return 0, 0, false
}

func tiffHasTag(b Buffer, order tiffByteOrder, ifdOffset uint32, tag uint16) bool {
	count, ok := tiffU16(b, order, int(ifdOffset))
	if !ok {
		return false
	}

	entryBase := int(ifdOffset) + 2
	entryEnd := entryBase + int(count)*12

	if entryBase < 0 || entryEnd > b.Len() {
		return false
	}

	for i := range int(count) {
		entry := entryBase + i*12

		currentTag, ok := tiffU16(b, order, entry)
		if !ok {
			return false
		}

		if currentTag == tag {
			return true
		}
	}

	return false
}

func tiffASCIIValueForTag(b Buffer, order tiffByteOrder, ifdOffset uint32, tag uint16) ([]byte, bool) {
	count, ok := tiffU16(b, order, int(ifdOffset))
	if !ok {
		return nil, false
	}

	entryBase := int(ifdOffset) + 2
	entryEnd := entryBase + int(count)*12

	if entryBase < 0 || entryEnd > b.Len() {
		return nil, false
	}

	for i := range int(count) {
		entry := entryBase + i*12

		currentTag, ok := tiffU16(b, order, entry)
		if !ok || currentTag != tag {
			continue
		}

		fieldType, ok := tiffU16(b, order, entry+2)
		if !ok || fieldType != 2 {
			return nil, false
		}

		valueCount, ok := tiffU32(b, order, entry+4)
		if !ok || valueCount == 0 {
			return nil, false
		}

		if valueCount <= 4 {
			end := entry + 8 + int(valueCount)
			if end > b.Len() {
				return nil, false
			}

			return bytes.TrimRight(b[entry+8:end], "\x00"), true
		}

		valueOffset, ok := tiffU32(b, order, entry+8)
		if !ok {
			return nil, false
		}

		if uint64(valueOffset) > uint64(b.Len()) || uint64(valueCount) > uint64(b.Len())-uint64(valueOffset) {
			return nil, false
		}

		start := int(valueOffset)
		end := start + int(valueCount)

		return bytes.TrimRight(b[start:end], "\x00"), true
	}

	return nil, false
}

func tiffU16(b Buffer, order tiffByteOrder, offset int) (uint16, bool) {
	if order == tiffLittleEndian {
		return b.U16LE(offset)
	}

	return b.U16BE(offset)
}

func tiffU32(b Buffer, order tiffByteOrder, offset int) (uint32, bool) {
	if order == tiffLittleEndian {
		return b.U32LE(offset)
	}

	return b.U32BE(offset)
}

func isTIFFHeader(b Buffer) bool {
	return b.Has(0, []byte{'I', 'I', 42, 0}) || b.Has(0, []byte{'M', 'M', 0, 42})
}

func DetectTorrent(b Buffer) *Metadata {
	if b.Len() < 32 || b[0] != 'd' {
		return nil
	}

	limit := min(b.Len(), 4096)
	data := b[:limit]

	if !bytes.Contains(data, []byte("8:announce")) || !bytes.Contains(data, []byte("4:info")) {
		return nil
	}

	return &Metadata{Kind: KindTorrentDocument}
}

func DetectFileTrailer(buffer Buffer) *Metadata {
	meta := DetectAppleDiskImage(buffer)
	if meta != nil {
		return meta
	}

	if buffer.Len() >= 48 && buffer.Has(buffer.Len()-8, []byte{0x57, 0xfb, 0x80, 0x8b, 0x24, 0x75, 0x47, 0xdb}) {
		return &Metadata{Kind: KindLevelDB}
	}

	if buffer.Len() < 512 {
		return nil
	}

	foot := buffer[buffer.Len()-512:]
	version, _ := foot.U32BE(12)
	diskType, _ := foot.U32BE(60)
	checksum, _ := foot.U32BE(64)

	if !foot.Has(0, []byte("conectix")) || version != 0x00010000 || diskType < 2 || diskType > 4 {
		return nil
	}

	var sum uint32

	for index, value := range foot {
		if index < 64 || index >= 68 {
			sum += uint32(value)
		}
	}

	if ^sum != checksum {
		return nil
	}

	return &Metadata{Kind: KindVHDDiskImage}
}

func DetectXMLSubtypes(b Buffer) *Metadata {
	data := bytes.TrimPrefix(b, []byte{0xef, 0xbb, 0xbf})

	if b.Has(0, []byte{0xff, 0xfe}) || b.Has(0, []byte{0xfe, 0xff}) {
		decoded, _, ok := TryDecodeUTF16(b)
		if !ok {
			return nil
		}

		data = decoded
	}

	data = bytes.TrimSpace(data)
	if len(data) == 0 || data[0] != '<' {
		return nil
	}

	decoder := xml.NewDecoder(bytes.NewReader(data))

	if b.Has(0, []byte{0xff, 0xfe}) || b.Has(0, []byte{0xfe, 0xff}) {
		decoder.CharsetReader = decodedXMLCharset
	}

	for {
		token, err := decoder.Token()
		if err != nil {
			return nil
		}

		if text, ok := token.(xml.CharData); ok && len(bytes.TrimSpace(text)) != 0 {
			return nil
		}

		if root, ok := token.(xml.StartElement); ok {
			return xmlRootMetadata(root)
		}
	}
}

func decodedXMLCharset(charset string, input io.Reader) (io.Reader, error) {
	switch strings.ToLower(charset) {
	case "utf-16", "utf-16le", "utf-16be":
		return input, nil
	default:
		return nil, errors.New("unsupported XML encoding")
	}
}

func xmlRootMetadata(root xml.StartElement) *Metadata {
	name := root.Name.Local
	namespace := root.Name.Space

	switch {
	case name == "svg" && namespace == "http://www.w3.org/2000/svg":
		return &Metadata{Kind: KindSVGImage}
	case name == "plist" && namespace == "":
		return &Metadata{Kind: KindAppleXMLPropertyList}
	case name == "kml" && (namespace == "http://www.opengis.net/kml/2.2" || namespace == "http://earth.google.com/kml/2.1"):
		return &Metadata{Kind: KindKeyholeMarkupLanguage}
	case name == "gpx" && (namespace == "http://www.topografix.com/GPX/1/1" || namespace == "http://www.topografix.com/GPX/1/0"):
		return &Metadata{Kind: KindGPSExchangeFormat}
	case name == "rss" && namespace == "":
		return &Metadata{Kind: KindRSSFeed}
	case name == "feed" && namespace == "http://www.w3.org/2005/Atom":
		return &Metadata{Kind: KindAtomFeed}
	case (name == "stylesheet" || name == "transform") && namespace == "http://www.w3.org/1999/XSL/Transform":
		return &Metadata{Kind: KindXMLDocument, Type: TypeXSLTStylesheet}
	case name == "Envelope" && (namespace == "http://schemas.xmlsoap.org/soap/envelope/" || namespace == "http://www.w3.org/2003/05/soap-envelope"):
		return &Metadata{Kind: KindSOAPMessage}
	case name == "COLLADA" && namespace == "http://www.collada.org/2005/11/COLLADASchema":
		return &Metadata{Kind: KindColladaModel}
	case name == "X3D" && (namespace == "" || namespace == "http://www.web3d.org/specifications/x3d-namespace"):
		return &Metadata{Kind: KindX3DModel}
	case namespace == "http://www.opengis.net/gml" || namespace == "http://www.opengis.net/gml/3.2":
		return &Metadata{Kind: KindGeographyMarkupLanguage}
	case name == "timedtext" && namespace == "":
		for _, attribute := range root.Attr {
			if attribute.Name.Local == "format" && attribute.Value == "3" {
				return &Metadata{Kind: KindYouTubeTimedText}
			}
		}
	case name == "assets" && namespace == "":
		return &Metadata{Kind: KindGameMakerStudioProject, Type: TypeGameMakerStudio, Confidence: ConfidenceMedium}
	}

	return &Metadata{Kind: KindXMLDocument, Confidence: ConfidenceMedium}
}

const (
	maxEOCDSize       = 22 + 65535
	maxCentralSize    = maxScanSize * 8
	maxSyntheticSize  = maxScanSize * 16
	centralHeaderSize = 46
	localHeaderSize   = 30
)

func DetectZIPContainer(b Buffer) *Metadata {
	if b.Len() < 4 || string(b[:4]) != "PK\x03\x04" {
		return nil
	}

	meta := detectZIPEntries(b[:min(b.Len(), maxScanSize)])

	refined := detectZIPReaderAt(bytes.NewReader(b), int64(b.Len()))
	if refined != nil {
		return refined
	}

	return meta
}

func detectZIPEntries(b Buffer) *Metadata {
	var (
		hasManifest         bool
		hasDex              bool
		hasAppxManifest     bool
		hasAppxSignature    bool
		hasSketchMeta       bool
		hasSketchUser       bool
		hasSketchDoc        bool
		hasManifestMF       bool
		hasWebXML           bool
		hasAppXML           bool
		hasMinecraftMeta    bool
		hasFabricMod        bool
		hasForgeMod         bool
		hasLottieManifest   bool
		hasLottieAnimations bool
		hasPyTorchData      bool
		hasPyTorchVersion   bool
		hasComicInfo        bool
		hasProcreateDoc     bool
		hasCeltxScript      bool
		hasStudioOneSong    bool
		hasPSVitaEboot      bool
		hasOsuBeatmap       bool
		hasOsuSkin          bool
		firstFile           = true
	)

	limit := b.Len() - 30
	zipMagic := []byte{'P', 'K', 3, 4}

	for i := 0; i <= limit; {
		idx := bytes.Index(b[i:], zipMagic)
		if idx == -1 {
			break
		}

		i += idx

		nameLen, ok := b.U16LE(i + 26)
		extraLen, extraOK := b.U16LE(i + 28)
		compressedSize, sizeOK := b.U32LE(i + 18)
		flags, flagsOK := b.U16LE(i + 6)

		dataStart := i + 30 + int(nameLen) + int(extraLen)

		if !ok || !extraOK || !sizeOK || !flagsOK || nameLen == 0 || dataStart < i || dataStart > b.Len() {
			i += 4

			continue
		}

		name := b[i+30 : i+30+int(nameLen)]

		if firstFile && string(name) == "mimetype" {
			compression, _ := b.U16LE(i + 8)

			dataEnd := dataStart + int(compressedSize)

			if compression == 0 && dataEnd >= dataStart && dataEnd <= b.Len() {
				switch string(b[dataStart:dataEnd]) {
				case "application/epub+zip":
					return &Metadata{Kind: KindZIPArchive, Type: TypeEPUBDocument}
				case "application/vnd.oasis.opendocument.text":
					return &Metadata{Kind: KindZIPArchive, Type: TypeOpenDocumentText}
				case "application/vnd.oasis.opendocument.spreadsheet":
					return &Metadata{Kind: KindZIPArchive, Type: TypeOpenDocumentSpreadsheet}
				case "application/vnd.oasis.opendocument.presentation":
					return &Metadata{Kind: KindZIPArchive, Type: TypeOpenDocumentPresentation}
				case "application/vnd.oasis.opendocument.graphics":
					return &Metadata{Kind: KindZIPArchive, Type: TypeOpenDocumentGraphics}
				case "application/vnd.oasis.opendocument.database":
					return &Metadata{Kind: KindZIPArchive, Type: TypeOpenDocumentDatabase}
				case "application/vnd.oasis.opendocument.formula":
					return &Metadata{Kind: KindZIPArchive, Type: TypeOpenDocumentFormula}
				case "application/vnd.oasis.opendocument.chart":
					return &Metadata{Kind: KindZIPArchive, Type: TypeOpenDocumentChart}
				case "application/vnd.oasis.opendocument.image":
					return &Metadata{Kind: KindZIPArchive, Type: TypeOpenDocumentImage}
				case "application/x-krita":
					return &Metadata{Kind: KindZIPArchive, Type: TypeKritaDocument}
				case "image/openraster":
					return &Metadata{Kind: KindZIPArchive, Type: TypeOpenRasterImage}
				}
			}
		}

		firstFile = false

		if matchASCII(name, "androidmanifest.xml") {
			hasManifest = true
		} else if hasSuffixASCII(name, ".dex") || matchASCII(name, "classes.dex") {
			hasDex = true
		} else if matchASCII(name, "appxmanifest.xml") {
			hasAppxManifest = true
		} else if matchASCII(name, "appxsignature.p7x") {
			hasAppxSignature = true
		} else if matchASCII(name, "document.json") {
			hasSketchDoc = true
		} else if matchASCII(name, "meta.json") {
			hasSketchMeta = true
		} else if matchASCII(name, "user.json") {
			hasSketchUser = true
		} else if matchASCII(name, "modules") {
			return &Metadata{Kind: KindZIPArchive, Type: TypeNone}
		} else if matchASCII(name, "meta-inf/manifest.mf") {
			hasManifestMF = true
		} else if matchASCII(name, "web-inf/web.xml") {
			hasWebXML = true
		} else if matchASCII(name, "meta-inf/application.xml") {
			hasAppXML = true
		} else if matchASCII(name, "pack.mcmeta") {
			hasMinecraftMeta = true
		} else if matchASCII(name, "fabric.mod.json") {
			hasFabricMod = true
		} else if matchASCII(name, "mcmod.info") || matchASCII(name, "meta-inf/mods.toml") {
			hasForgeMod = true
		} else if matchASCII(name, "model.weights.h5") {
			return &Metadata{Kind: KindZIPArchive, Type: TypeKerasModel}
		} else if hasSuffixASCII(name, "/data.pkl") || matchASCII(name, "data.pkl") {
			hasPyTorchData = true
		} else if hasSuffixASCII(name, "/version") || matchASCII(name, "version") {
			hasPyTorchVersion = true
		} else if matchASCII(name, "main.lua") {
			return &Metadata{Kind: KindZIPArchive, Type: TypeLOVEGame}
		} else if matchASCII(name, "doc.kml") {
			return &Metadata{Kind: KindZIPArchive, Type: TypeKMZArchive}
		} else if hasSuffixASCII(name, ".dist-info/wheel") {
			return &Metadata{Kind: KindZIPArchive, Type: TypePythonWheel}
		} else if matchASCII(name, "manifest.json") {
			hasLottieManifest = true

			if bytes.Contains(b, []byte("xapk_version")) {
				return &Metadata{Kind: KindZIPArchive, Type: TypeAndroidPackageX}
			}

			if bytes.Contains(b, []byte("browser_specific_settings")) {
				return &Metadata{Kind: KindZIPArchive, Type: TypeFirefoxExtension}
			}
		} else if matchASCII(name, "install.rdf") {
			return &Metadata{Kind: KindZIPArchive, Type: TypeFirefoxExtension}
		} else if hasPrefixASCII(name, "animations/") {
			hasLottieAnimations = true
		} else if hasPrefixASCII(name, "payload/") && hasSuffixASCII(name, ".app/info.plist") && bytes.Count(name, []byte{'/'}) == 2 {
			return &Metadata{Kind: KindZIPArchive, Type: TypeIOSApplicationArchive}
		} else if matchASCII(name, "bundleconfig.pb") {
			return &Metadata{Kind: KindZIPArchive, Type: TypeAndroidAppBundle}
		} else if matchASCII(name, "toc.pb") {
			return &Metadata{Kind: KindZIPArchive, Type: TypeAndroidSplitAPKSet}
		} else if bytes.Contains(name, []byte("apex_manifest")) {
			return &Metadata{Kind: KindZIPArchive, Type: TypeAndroidSystemPackage}
		} else if matchASCII(name, "extension.vsixmanifest") {
			return &Metadata{Kind: KindZIPArchive, Type: TypeVisualStudioExtension}
		} else if matchASCII(name, "3d/3dmodel.model") {
			return &Metadata{Kind: KindZIPArchive, Type: Type3MFDocument}
		} else if hasSuffixASCII(name, ".nuspec") {
			return &Metadata{Kind: KindZIPArchive, Type: TypeNuGetPackage}
		} else if matchASCII(name, "comicinfo.xml") {
			hasComicInfo = true
		} else if matchASCII(name, "document.archive") {
			hasProcreateDoc = true
		} else if matchASCII(name, "script.html") || matchASCII(name, "project.rdf") {
			hasCeltxScript = true
		} else if matchASCII(name, "song.xml") || matchASCII(name, "project.xml") {
			hasStudioOneSong = true
		} else if matchASCII(name, "eboot.bin") || matchASCII(name, "sce_sys/param.sfo") {
			hasPSVitaEboot = true
		} else if hasSuffixASCII(name, ".osu") {
			hasOsuBeatmap = true
		} else if matchASCII(name, "skin.ini") {
			hasOsuSkin = true
		} else if matchASCII(name, "metadata/buildversionhistory.plist") || hasPrefixASCII(name, "index/document.iwa") {
			return &Metadata{Kind: KindAppleiWorkDocument}
		}

		if flags&0x08 != 0 || uint64(dataStart)+uint64(compressedSize) > uint64(b.Len()) {
			break
		}

		i = dataStart + int(compressedSize)
	}

	limitSearch := min(b.Len(), 32768)
	searchArea := b[:limitSearch]

	if hasManifest {
		if hasDex {
			return &Metadata{Kind: KindZIPArchive, Type: TypeAndroidPackage}
		}

		return &Metadata{Kind: KindZIPArchive, Type: TypeAndroidArchive}
	}

	if hasAppxManifest {
		if hasAppxSignature {
			return &Metadata{Kind: KindZIPArchive, Type: TypeMSIXPackage}
		}

		return &Metadata{Kind: KindZIPArchive, Type: TypeAPPXPackage}
	}

	if hasSketchDoc && (hasSketchMeta || hasSketchUser) {
		if bytes.Contains(searchArea, []byte("com.bohemiancoding.sketch")) || bytes.Contains(searchArea, []byte("com.sketch3")) {
			return &Metadata{Kind: KindSketchDocument}
		}
	}

	if hasManifestMF {
		if hasWebXML {
			return &Metadata{Kind: KindZIPArchive, Type: TypeJavaWebArchive}
		}

		if hasAppXML {
			return &Metadata{Kind: KindZIPArchive, Type: TypeJavaEnterpriseArchive}
		}

		if hasFabricMod {
			return &Metadata{Kind: KindZIPArchive, Type: TypeFabricMod}
		}

		if hasForgeMod {
			return &Metadata{Kind: KindZIPArchive, Type: TypeForgeMod}
		}

		if hasMinecraftMeta {
			return &Metadata{Kind: KindZIPArchive, Type: TypeMinecraftResourcePack}
		}

		return &Metadata{Kind: KindZIPArchive, Type: TypeJavaArchive}
	}

	if hasLottieManifest && hasLottieAnimations {
		return &Metadata{Kind: KindLottieAnimation}
	}

	if hasPyTorchData && hasPyTorchVersion {
		return &Metadata{Kind: KindZIPArchive, Type: TypePyTorchModel}
	}

	if hasComicInfo {
		return &Metadata{Kind: KindZIPArchive, Type: TypeComicBook}
	}

	if hasProcreateDoc {
		return &Metadata{Kind: KindZIPArchive, Type: TypeProcreate}
	}

	if hasCeltxScript {
		return &Metadata{Kind: KindZIPArchive, Type: TypeCeltx}
	}

	if hasStudioOneSong {
		return &Metadata{Kind: KindZIPArchive, Type: TypeStudioOne}
	}

	if hasPSVitaEboot {
		return &Metadata{Kind: KindZIPArchive, Type: TypePSVita}
	}

	if hasOsuBeatmap {
		return &Metadata{Kind: KindZIPArchive, Type: TypeOsuBeatmap}
	}

	if hasOsuSkin {
		return &Metadata{Kind: KindZIPArchive, Type: TypeOsuSkin}
	}

	return &Metadata{Kind: KindZIPArchive}
}

func detectZIPReaderAt(r io.ReaderAt, size int64) *Metadata {
	if size < 22 {
		return nil
	}

	tailSize := min(size, int64(maxEOCDSize))
	tail := make([]byte, int(tailSize))

	if !readAtExactly(r, tail, size-tailSize) {
		return nil
	}

	eocd := -1
	searchEnd := len(tail)

	for searchEnd >= 4 {
		candidate := bytes.LastIndex(tail[:searchEnd], []byte{'P', 'K', 5, 6})
		if candidate < 0 {
			break
		}

		if candidate+22 <= len(tail) {
			commentLength, _ := Buffer(tail).U16LE(candidate + 20)
			if candidate+22+int(commentLength) == len(tail) {
				eocd = candidate

				break
			}
		}

		searchEnd = candidate
	}

	if eocd < 0 {
		return nil
	}

	tailBuffer := Buffer(tail)

	disk, _ := tailBuffer.U16LE(eocd + 4)
	centralDisk, _ := tailBuffer.U16LE(eocd + 6)
	entriesOnDisk, _ := tailBuffer.U16LE(eocd + 8)
	entryCount, _ := tailBuffer.U16LE(eocd + 10)
	centralSize, _ := tailBuffer.U32LE(eocd + 12)
	centralOffset, _ := tailBuffer.U32LE(eocd + 16)
	eocdOffset := size - tailSize + int64(eocd)

	if disk != 0 || centralDisk != 0 || entriesOnDisk != entryCount || entryCount == 0 || entryCount == 0xffff || centralSize == 0xffffffff || centralOffset == 0xffffffff || centralSize > maxCentralSize || int64(centralOffset)+int64(centralSize) != eocdOffset {
		return nil
	}

	central := make([]byte, int(centralSize))
	if !readAtExactly(r, central, int64(centralOffset)) {
		return nil
	}

	entryData := make([]byte, 0, min(maxSyntheticSize, int(centralSize)))

	var (
		offset           int
		firstLocalOffset uint32
		firstName        []byte
	)

	for i := 0; i < int(entryCount); i++ {
		if offset+centralHeaderSize > len(central) || !bytes.Equal(central[offset:offset+4], []byte{'P', 'K', 1, 2}) {
			return nil
		}

		record := Buffer(central[offset:])

		nameLength, _ := record.U16LE(28)
		extraLength, _ := record.U16LE(30)
		commentLength, _ := record.U16LE(32)
		localOffset, _ := record.U32LE(42)

		recordSize := centralHeaderSize + int(nameLength) + int(extraLength) + int(commentLength)

		if nameLength == 0 || recordSize > len(central)-offset || len(entryData)+localHeaderSize+int(nameLength) > maxSyntheticSize {
			return nil
		}

		name := central[offset+centralHeaderSize : offset+centralHeaderSize+int(nameLength)]

		if i == 0 {
			firstLocalOffset = localOffset
			firstName = name
		}

		start := len(entryData)

		entryData = append(entryData, make([]byte, localHeaderSize)...)

		entryData[start] = 'P'
		entryData[start+1] = 'K'
		entryData[start+2] = 3
		entryData[start+3] = 4
		entryData[start+26] = byte(nameLength)
		entryData[start+27] = byte(nameLength >> 8)

		entryData = append(entryData, name...)

		offset += recordSize
	}

	if offset != len(central) || int64(firstLocalOffset) >= int64(centralOffset) {
		return nil
	}

	local := make([]byte, localHeaderSize+len(firstName))

	if !readAtExactly(r, local, int64(firstLocalOffset)) || !bytes.Equal(local[:4], []byte{'P', 'K', 3, 4}) {
		return nil
	}

	localBuffer := Buffer(local)

	localNameLength, _ := localBuffer.U16LE(26)

	if int(localNameLength) != len(firstName) || !bytes.Equal(local[localHeaderSize:localHeaderSize+len(firstName)], firstName) {
		return nil
	}

	meta := detectZIPEntries(Buffer(entryData))

	refined := detectOOXML(r, size, central)
	if refined != nil {
		return refined
	}

	return meta
}

func readAtExactly(r io.ReaderAt, data []byte, offset int64) bool {
	n, err := r.ReadAt(data, offset)
	return n == len(data) && (err == nil || errors.Is(err, io.EOF))
}

func matchASCII(b []byte, lower string) bool {
	if len(b) != len(lower) {
		return false
	}

	for i := range b {
		c := b[i]
		if c >= 'A' && c <= 'Z' {
			c += 32
		}

		if c != lower[i] {
			return false
		}
	}

	return true
}

func hasSuffixASCII(b []byte, lowerSuffix string) bool {
	if len(b) < len(lowerSuffix) {
		return false
	}

	return matchASCII(b[len(b)-len(lowerSuffix):], lowerSuffix)
}

func hasPrefixASCII(b []byte, lowerPrefix string) bool {
	if len(b) < len(lowerPrefix) {
		return false
	}

	return matchASCII(b[:len(lowerPrefix)], lowerPrefix)
}

func DetectZlib(b Buffer) *Metadata {
	if b.Len() < 2 {
		return nil
	}

	cmf := b[0]
	flg := b[1]

	if cmf&0x0f != 8 {
		return nil
	}

	if cmf>>4 > 7 {
		return nil
	}

	if (uint16(cmf)<<8|uint16(flg))%31 != 0 {
		return nil
	}

	return &Metadata{
		Kind:       KindZlibData,
		Confidence: ConfidenceMedium,
	}
}
